import{_ as s,o as a,c as n,a0 as i}from"./chunks/framework.CNoGN0p1.js";const t="/phenoblend/assets/genes.C17xBUiz.png",o="/phenoblend/assets/genes2.DU4TZ_1u.png",f=JSON.parse('{"title":"Genes and diseases","description":"","frontmatter":{},"headers":[],"relativePath":"tutorial/genes.md","filePath":"tutorial/genes.md"}'),r={name:"tutorial/genes.md"};function d(l,e,h,c,p,g){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="genes-and-diseases" tabindex="-1">Genes and diseases <a class="header-anchor" href="#genes-and-diseases" aria-label="Permalink to &quot;Genes and diseases&quot;">​</a></h1><p>Up to 5% of individuals with a diagnosed genetic disease have multiple distinct genetic diseases. The phenotypic profiles of affected individuals result from a “blend” of the clinical manifestations of each disease, whereby individual features can either be assigned to a specific disease or be attributed to more than one disease. This situation has been referred to in the literature as blended phenotype, dual (or multiple) genetic diagnosis, Multilocus Genomic Variation, composite phenotype, co-occurrence of diseases, comorbidity, and others. For conciseness, we will use the acronym MGD (multiple genetic diagnosis).</p><h2 id="entering-gene-disease-data" tabindex="-1">Entering gene/disease data <a class="header-anchor" href="#entering-gene-disease-data" aria-label="Permalink to &quot;Entering gene/disease data&quot;">​</a></h2><p>Phenoblend is intended to display the blends and degree of overlap of the clinical manifestations of an individual with an MGD. Users of phenoblend need to enter the two (or more) gene symbols of the diseases that have been diagnosed. First, enter the gene symbol into the search box (which has autocomplete function).</p><p><img src="'+t+'" alt="Genes: enter a gene symbol"><em>Figure 3. Enter the symbol of a gene in which a causal variant was identified.</em></p><p>If possible, indicate the specific disease diagnosis if a gene is associated with more than one disease. In the following example, we have entered information about an individual diagnosed with both <a href="https://omim.org/entry/162200" target="_blank" rel="noreferrer">Neurofibromatosis type 1</a> and <a href="https://omim.org/entry/163950?search=noonan&amp;highlight=noonan" target="_blank" rel="noreferrer">Noonan syndrome 1</a></p><p><img src="'+o+'" alt="Genes: enter a gene symbol"><em>Figure 4. If possible, specify the disease diagnosis.</em></p><p>If the clinical diagnosis at the disease level is unknown, users can choose all diseases, and the disease model will contain the union of observed HPO terms of all of the diseases.</p>',8)])])}const u=s(r,[["render",d]]);export{f as __pageData,u as default};
